-- The text above each PaperCept "Submit a contribution" table (venues.details.schedule.intro / notes / footnote),
-- shown under "Submit a Contribution to <event>" on the event page. Links to PaperCept's own Support and PDF test pages left out.
update venues set details = jsonb_set(details, '{schedule}', (details->'schedule') || '{"intro": ["Check the submission deadlines and follow the appropriate link if the site is open for submission.", "The site opens for submission at 00:00 hrs server time on the date indicated.", "The site closes for submission at 24:00 hrs (midnight) server time on the date indicated."], "notes": [{"title": "Compliant conversion", "text": "AdCONIP 2026 subscribes to the PaperCept Compliant PDF Creation service. Simply upload the Word or LaTeX source file of your submission and the service converts it to compliant pdf. Be sure to use the Word template or LaTeX style file provided by the conference and follow the conference instructions concerning paper size, number of pages and page margins. It is the author''s responsibility to use the correct template or style file and visually check the output from this automated pdf conversion process. PaperCept is not liable for inaccuracies in the generated output."}], "footnote": "All deadlines are 23:59:59 Pacific Time."}'::jsonb) where slug = 'adconip-2026' and details ? 'schedule';
update venues set details = jsonb_set(details, '{schedule}', (details->'schedule') || '{"intro": ["Check the submission deadlines and follow the appropriate link if the site is open for submission.", "The site opens for submission at 00:00 hrs server time on the date indicated.", "The site closes for submission at 24:00 hrs (midnight) server time on the date indicated."], "notes": [{"title": "Compliant conversion of pdf files", "text": "ICSTCC 2026 supports compliant conversion of pdf files. Upload the pdf file of your submission and the system converts it to compliant pdf, satisfying all technical requirements regarding pdf version and font embedding. Be sure to use the Word template or LaTeX style file provided by the conference and follow the conference instructions concerning paper size, number of pages and page margins while preparing your contribution. It is the author''s responsibility to use the correct template or style file and visually check the output from this automated pdf conversion process. PaperCept is not liable for inaccuracies in the generated output."}], "footnote": "All deadlines are 23:59:59 Pacific Time."}'::jsonb) where slug = 'icstcc-2026' and details ? 'schedule';
